        c.g[A2][0] = c.g[A3][0];
        c.g[A0][0] = Addr(self_at).off(0x54c).lw(c);
        c.g[A3][0] = c.g[T0][0];
        c.g[T0][0] = c.g[T1][0];
        c.g[A0][0] = add32(c.g[A0][0], c.g[V1][0]);
        c.g[T1][0] = c.g[T2][0];
        c.g[T2][0] = c.g[T3][0];
