            c.g[V0][0] = 2;
            c.g[A2][0] = c.g[S2][0];
            c.sw(c.g[S3][0] as u32, c.g[V0][0]);
            c.g[A3][0] = c.g[S5][0];
            c.g[A0][0] = sx((c.g[S0][0] as u32).wrapping_add(0xa38));
            c.g[V0][0] = c.lw((c.g[S0][0] as u32).wrapping_add(CURRENT_BANK));
            c.sw(c.g[S4][0] as u32, c.g[V0][0]);
