                c.g[S1][0] = c.g[T1][0];
                c.g[V0][0] = ((c.g[S1][0] as i64) < (c.g[V0][0] as i64)) as u64;
                let t = c.g[V0][0] != 0;
                c.g[S0][0] = c.lw(apply_ea(c.g[SP][0], 0x4));
