            c.g[V0][0] = c.lw(apply_ea(c.g[SP][0], 0x8));
            let t = (c.g[V0][0] as i64) <= 0;
            c.g[V0][0] = c.lw(apply_ea(c.g[SP][0], 0x10));
            if t {
                break 'b_280afc;
            }
            c.cycles += 2;
            c.g[S0][0] = 0xff;
