    #[test]
    fn script_engine_pop_free_node_matches() {
        check(
            ssx3_ee::s07::f_0027bd78,
            script_engine_pop_free_node,
            200,
            &|c, seed| {
                let mut r = Rng(0x27bd_78 ^ seed as u64);
                scramble(c, &mut r);
                c.g[A0][0] = DATA as u64;
                let node = DATA + 0x100;
                c.bus
                    .write32(DATA + 0x548, if seed % 5 == 0 { 0 } else { node });
                c.bus
                    .write32(node + 0x10, if seed % 4 == 0 { 0 } else { DATA + 0x140 });
            },
        );
    }

    #[test]
    fn script_engine_push_free_node_matches() {
        check(
            ssx3_ee::s07::f_0027bd90,
            script_engine_push_free_node,
            200,
            &|c, seed| {
                let mut r = Rng(0x27bd_90 ^ seed as u64);
                scramble(c, &mut r);
                c.g[A0][0] = DATA as u64;
                let node = DATA + 0x100;
                c.g[A1][0] = (node as u64) | ((r.next_u32() as u64) << 32);
                c.bus.write32(DATA + 0x548, r.next_u32());
                for i in 0..5 {
                    c.bus.write32(node + i * 4, r.next_u32());
                }
            },
        );
    }

