    /// A zeroed script-object dummy with the vtable slot_2 4 used by
    /// `ScriptObjCam_Deactivate`.
    pub(crate) fn scrub(c: &mut Cpu, at_2: u32) -> u32 {
        let vt = at_2 + 0x1000;
        w(c, at_2 + 0x14, vt);
        slot_2(c, vt, 0x20, 0, FAKE);
        at_2
    }

