    /// The skip delay counts 60 Hz frames: the 30 `GameStateEventSelect`
    /// sets lasts 30 updates at 60 Hz and the same time at 120 / 240 Hz.
    #[test]
    fn script_engine_update_skip_delay_follows_the_rate() {
        let updates = |hz: u32| {
            let mut c = crate::difftest::fresh();
            let c = &mut *c;
            // Seed 2: the engine idle (+0x550 = 2), straight to the delay.
            let _ = script_engine_fixture(c, 2, 0);
            w(c, SE_ENGINE + 0x554, 30);
            crate::tick::set_for_test(c, hz);
            let mut n = 0;
            while c.bus.read32(SE_ENGINE + 0x554) != 0 {
                n += 1;
                assert!(n < 1000);
                c.pc = 0x0027_8720;
                c.g[A0][0] = sx(SE_ENGINE);
                script_engine_update(c);
                assert_eq!(c.pc, TEST_RA, "{hz} Hz: update {n} did not return");
            }
            n
        };
        assert_eq!(updates(60), 30);
        for hz in [120u32, 240] {
            let q = hz / 60;
            assert_eq!(updates(hz), 30 * q - (q - 1), "{hz} Hz");
        }
    }

    // ---------------------------------------------- ScriptAudioObj_UpdateSounds

    /// `ScriptAudioObj_UpdateSounds`: four triggers each without a sound,
    /// with a stop request, or polling an id the bank monitor may or may
    /// not still play (64 busy / free instances that are already fading, so
    /// the real stop resets them without SND calls); a pending speech cue
    /// with speech instance 0 missing or ready (the real list skip runs on
    /// a list in state 3 that returns at once).
    #[test]
    fn script_audio_obj_update_sounds_matches() {
        check(
            ee::s07::f_00280640__generated,
            script_audio_obj_update_sounds,
            300,
            &|c, seed| {
                let mut r = machine(c, seed, 0x0028_0640, 0);
                c.pc = 0x0028_0640;
                let this = DATA + 0x1_0000;
                let audio = DATA + 0x1000;
                let root = DATA + 0x2000;
                let snd = DATA + 0x3000;
                let insts = DATA + 0x20_0000;
                c.bus.write32(GAME_GP + 0x410, audio);
                c.bus.write32(audio + 0x118, root);
                c.bus.write32(root, snd);
                c.bus.write32(snd + 0x1d8 + 0x8ec, insts);
                for i in 0..64 {
                    let inst = insts + i * 0xc0;
                    c.bus.write32(inst, r.next_u32() % 3);
                    c.bus.write32(inst + 4, r.next_u32() % 6);
                    c.bus.write32(inst + 0x54, 1);
                    c.bus.write32(inst + 0x9c, 0);
                }
                for k in 0..4 {
                    let t = this + 0xbc + 0xc * k;
                    let id = match r.next_u32() % 4 {
                        0 => r.next_u32() | 0x8000_0000,
                        _ => r.next_u32() % 6,
                    };
                    c.bus.write32(t, id);
                    c.bus.write32(
                        t + 4,
                        if r.next_u32() % 3 == 0 {
                            r.next_u32() | 1
                        } else {
                            0
                        },
                    );
                    c.bus.write32(t + 8, r.next_u32());
                }
                c.bus.write32(
                    this + 0xf4,
                    if seed % 3 == 0 { 0 } else { r.next_u32() | 1 },
                );
                // Speech: instance 0 missing or with a stream slot whose
                // stream is gone (ready).
                let speech = audio + 0x5560;
                let spch_insts = DATA + 0x4000;
                let spch = DATA + 0x4100;
                let arrays = DATA + 0x4200;
                let array = DATA + 0x4300;
                let table = DATA + 0x4400;
                c.bus.write32(speech + 4, spch_insts);
                c.bus
                    .write32(spch_insts, if seed % 2 == 0 { 0 } else { spch });
                c.bus.write32(spch + 4, r.next_u32() % 4);
                c.bus.write32(GAME_GP + 0x6c4, arrays);
                c.bus.write32(arrays, array);
                c.bus.write32(array + 8, table);
                // The script engine and its list (state 3, nothing queued).
                let engine = DATA + 0x5000;
                let lists = DATA + 0x6000;
                let index = r.next_u32() % 4;
                let list = lists + 0xcc * index;
                c.bus.write32(GAME_GP - 0x84c, engine);
                c.bus.write32(engine + 0x550, index);
                c.bus.write32(engine + 0x54c, lists);
                c.bus.write32(list + 0xa4, 3);
                c.bus.write32(list + 0xa8, 1);
                c.bus.write32(list + 0xbc, 0);
                c.bus.write32(list + 0xc0, 0);
                c.g[A0][0] = sx(this);
            },
        );
    }

    // ---------------------------------------------- ScriptEngine_PollAsyncLoads

    /// `ScriptEngine_PollAsyncLoads`: no pending loads; a filter handle that
    /// is unknown (`AsyncFile_IsDone` -1: the handler runs), still loading
    /// (0: skipped) or absent; bank slots mixing empty, loading and finished
    /// handles. The handlers take their short paths: `AsyncFile_GetResult`
    /// of an unknown handle leaves the size word on the stack, which the
    /// fixture zeroes (filter: nothing loaded; bank: the slot is cleared).
    /// The mutex syscalls are fakes, some of which unwind.
    #[test]
    fn script_engine_poll_async_loads_matches() {
        use crate::difftest::fakes::machine;
        use crate::difftest::{check, DATA, SP};
        /// `AsyncFile_FromHandle`'s table: count and pointer to 0x30-byte
        /// entries (handle at +0, request state at +0x1c).
        const FILE_COUNT: u32 = 0x0051_9bf0;
        const FILE_TABLE_PTR: u32 = 0x0045_0c34;
        const FILE_TABLE: u32 = DATA + 0x20_0000;
        check(
            ee::s07::f_00278918__generated,
            script_engine_poll_async_loads,
            300,
            &|c, seed| {
                let mut r = machine(c, seed, 0x0027_8918, 12);
                c.pc = 0x0027_8918;
                let this = DATA;
                c.g[A0][0] = sx(this);
                // Four known files, all still loading (state non-zero).
                c.bus.write32(FILE_COUNT, 4);
                c.bus.write32(FILE_TABLE_PTR, FILE_TABLE);
                let loading = |i: u32| 0x100 * (i + 1) + i;
                for i in 0..4 {
                    c.bus.write32(FILE_TABLE + 0x30 * i, loading(i));
                    c.bus
                        .write32(FILE_TABLE + 0x30 * i + 0x1c, r.next_u32() | 1);
                }
                let unknown =
                    |r: &mut crate::difftest::Rng| 0x1000 + (r.next_u32() & 0xff00) + 0x10;
                c.bus.write32(
                    this + SCRIPT_PENDING_LOADS,
                    if seed % 6 == 0 { 0 } else { r.next_u32() | 1 },
                );
                let filter = match seed % 3 {
                    0 => 0,
                    1 => loading(r.next_u32() % 4),
                    _ => unknown(&mut r),
                };
                c.bus.write32(this + SCRIPT_FILTER_HANDLE, filter);
                for i in 0..10 {
                    let h = match r.next_u32() % 4 {
                        0 | 1 => 0,
                        2 => loading(r.next_u32() % 4),
                        _ => unknown(&mut r),
                    };
                    c.bus
                        .write32(this + SCRIPT_BANK_HANDLES + SCRIPT_BANK_SLOT_SIZE * i, h);
                }
                // The handlers' `AsyncFile_GetResult` size words (their frames
                // below ours): zero, so they take the short paths.
                c.bus.write32(SP - 0x50 - 0x30 + 0x4, 0);
                c.bus.write32(SP - 0x50 - 0xf0 + 0x84, 0);
            },
        );
    }

    /// ScriptEngine_ToggleMoviePause: the real ScriptMovie_TogglePause on
    /// the movie at engine + 0x500 (no player, not playing, pause or resume
    /// requested, player paused or not), as in its own test.
    #[test]
    fn script_engine_toggle_movie_pause_matches() {
        check(
            ee::s07::f_002789c0__generated,
            script_engine_toggle_movie_pause,
            200,
            &|c, seed| {
                let mut r = fakes::machine(c, seed, 0x27_89c0, 0);
                let engine = DATA;
                let movie = engine + 0x500;
                let player = DATA + 0x1000;
                let flag = |r: &mut Rng, k: u32| {
                    if (seed >> k) & 1 == 0 {
                        0
                    } else {
                        r.next_u32() | 1
                    }
                };
                c.bus.write32(movie, if seed % 9 == 8 { 0 } else { player });
                c.bus
                    .write32(movie + 4, if seed % 7 == 6 { 0 } else { r.next_u32() | 1 });
                c.bus.write32(movie + 8, flag(&mut r, 0));
                c.bus.write32(player + 8, flag(&mut r, 1));
                c.bus.write32(
                    player + 0x38,
                    flag(&mut r, 2) & (seed / 4 % 2).wrapping_neg(),
                );
                c.bus.write32(player + 0x3c, 0);
                c.g[A0][0] = sx(engine);
                c.pc = 0x0027_89c0;
            },
        );
    }

